317	    /**
318	     * Build the unified member id for a new owner as {@code '<REGION><FY><HASH8><CHK>'}, where REGION is
319	     * the region code derived from the postcode (falling back to the city-to-region table, else
320	     * {@code "UNKNOWN"}), FY is the two-digit fiscal year (starting 1 July) of the
321	     * business-day-adjusted {@code registrationDate}, HASH8 is the first 8 upper-case hex characters of
322	     * the SHA-256 digest over {@code normalizedTelephone + lastName}, and CHK is a single Luhn check
323	     * digit computed over the digits of {@code '<REGION><FY><HASH8>'}. The id depends only on the
324	     * owner's own region, fiscal year and identity, not on how many owners already exist.
325	     */
326	    private String nextMemberId(String region, LocalDate registrationDate,
327	                                String normalizedTelephone, String lastName) {
328	        String fiscalYear = String.format("%02d", fiscalYearStart(registrationDate) % 100);
329	        String hash8 = hash8(normalizedTelephone + (lastName == null ? "" : lastName));
330	        String base = region + fiscalYear + hash8;
331	        return base + luhnCheckDigit(base);
332	    }
333	
334	    /**
335	     * De-duplicate a computed member id against the ids already assigned to existing owners: when
336	     * {@code memberId} is unused it is returned unchanged, otherwise {@code '-<n>'} is appended with
337	     * the smallest {@code n} of 2 or more that makes the result unique among existing owners.
338	     */
339	    private String deduplicateMemberId(String memberId) {
340	        Set<String> existing = this.clinicService.findAllOwners().stream()
341	            .map(Owner::getMemberId)
342	            .filter(Objects::nonNull)
343	            .collect(Collectors.toSet());
344	        if (!existing.contains(memberId)) {
345	            return memberId;
346	        }
347	        int n = 2;
348	        while (existing.contains(memberId + "-" + n)) {
349	            n++;
350	        }
351	        return memberId + "-" + n;
352	    }
353	
354	    /**
355	     * The starting calendar year of the fiscal year (which starts on 1 July) that contains the given
356	     * date: the date's own year when it falls on or after 1 July, otherwise the previous year.
357	     */
358	    private static int fiscalYearStart(LocalDate date) {
359	        return date.getMonthValue() >= 7 ? date.getYear() : date.getYear() - 1;
360	    }
361	
362	    /**
363	     * A single Luhn check digit (0-9) computed over the digits contained in {@code input}
364	     * (non-digit characters are ignored).
365	     */
366	    private static int luhnCheckDigit(String input) {
367	        int sum = 0;
368	        boolean dbl = true;
369	        for (int i = input.length() - 1; i >= 0; i--) {
370	            char c = input.charAt(i);
371	            if (c < '0' || c > '9') {
372	                continue;
373	            }
374	            int d = c - '0';
375	            if (dbl) {
376	                d *= 2;
377	                if (d > 9) {
378	                    d -= 9;
379	                }
380	            }
381	            sum += d;
382	            dbl = !dbl;
383	        }
384	        return (10 - (sum % 10)) % 10;
385	    }
386	
387	    /**
388	     * First 8 upper-case hex characters of the SHA-256 digest of the UTF-8 bytes of {@code input}.
389	     */
390	    private static String hash8(String input) {
391	        return hashHex(input, 8, true);
392	    }
393	
394	    /**
395	     * First {@code length} hex characters of the SHA-256 digest of the UTF-8 bytes of {@code input},
396	     * upper-cased when {@code upperCase} is true and lower-cased otherwise.
397	     */
398	    private static String hashHex(String input, int length, boolean upperCase) {
399	        try {
400	            byte[] digest = MessageDigest.getInstance("SHA-256")
401	                .digest(input.getBytes(StandardCharsets.UTF_8));
402	            StringBuilder sb = new StringBuilder(digest.length * 2);
403	            for (byte b : digest) {
404	                sb.append(String.format("%02x", b));
405	            }
406	            String hex = sb.substring(0, length);
407	            return upperCase ? hex.toUpperCase() : hex;
408	        }
409	        catch (java.security.NoSuchAlgorithmException e) {
410	            throw new IllegalStateException(e);
411	        }
412	    }
