414	    /**
415	     * Resolve an owner's region preferring the postcode: the region is taken from the postcode range
416	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) when the postcode resolves, otherwise from the
417	     * fixed city-to-region table, else {@code "UNKNOWN"}.
418	     */
419	    private static String region(String postcode, String city) {
420	        String fromPostcode = regionForPostcode(postcode);
421	        return fromPostcode != null ? fromPostcode : regionForCity(city);
422	    }
423	
424	    /**
425	     * Region for a 4-digit postcode by inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099),
426	     * or {@code null} when the postcode is absent, not exactly 4 digits, or in no known range.
427	     */
428	    private static String regionForPostcode(String postcode) {
429	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
430	            return null;
431	        }
432	        int value = Integer.parseInt(postcode);
433	        for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
434	            int[] range = entry.getValue();
435	            if (value >= range[0] && value <= range[1]) {
436	                return entry.getKey();
437	            }
438	        }
439	        return null;
440	    }
