442	    /**
443	     * Roll a registration date forward to the next business day: when it falls on a Saturday or
444	     * Sunday, or on a listed public holiday, it is advanced day by day to the next non-holiday
445	     * weekday; ordinary weekday dates are returned unchanged.
446	     */
447	    static LocalDate toBusinessDay(LocalDate date) {
448	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
449	            || date.getDayOfWeek() == DayOfWeek.SUNDAY
450	            || PUBLIC_HOLIDAYS.contains(date)) {
451	            date = date.plusDays(1);
452	        }
453	        return date;
454	    }
