456	    /**
457	     * Count the owners already created on the business day that {@code registrationDate} rolls to,
458	     * using the same per-day accumulation path as the daily create-limit rule.
459	     */
460	    private long ownersCreatedOn(LocalDate registrationDate) {
461	        LocalDate day = toBusinessDay(registrationDate);
462	        return this.clinicService.findAllOwners().stream()
463	            .map(Owner::getRegistrationDate)
464	            .filter(existing -> existing != null)
465	            .map(OwnerRestControllerV1::toBusinessDay)
466	            .filter(day::equals)
467	            .count();
468	    }
