470	    /**
471	     * Region -> inclusive 4-digit postcode range {@code {low, high}} used to validate a supplied
472	     * postcode against the owner's city region.
473	     */
474	    private static final java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
475	        "NSW", new int[] {2000, 2099},
476	        "VIC", new int[] {3000, 3099},
477	        "QLD", new int[] {4000, 4099});
478	
479	    /**
480	     * Resolve an owner's region from the city using the fixed city-to-region table
481	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}); {@code "UNKNOWN"}
482	     * when the city is not listed.
483	     */
484	    private static String regionForCity(String city) {
485	        return switch (city == null ? "" : city) {
486	            case "Sydney" -> "NSW";
487	            case "Melbourne" -> "VIC";
488	            case "Brisbane" -> "QLD";
489	            default -> "UNKNOWN";
490	        };
491	    }
492	
493	    /**
494	     * Validate a supplied postcode: it must be exactly 4 digits, and when the owner's city maps to a
495	     * known region the numeric value must fall within that region's inclusive range (NSW 2000-2099,
496	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
497	     */
498	    private static boolean isPostcodeValid(String postcode, String city) {
499	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
500	            return false;
501	        }
502	        int[] range = REGION_POSTCODES.get(regionForCity(city));
503	        if (range == null) {
504	            return true;
505	        }
506	        int value = Integer.parseInt(postcode);
507	        return value >= range[0] && value <= range[1];
508	    }
