510	    /**
511	     * Whether the email's domain (the part after the final '@') is on the disposable-domain
512	     * blocklist. A {@code null} email is not disposable; the comparison is case-insensitive.
513	     */
514	    private static boolean isDisposableEmailDomain(String email) {
515	        if (email == null) {
516	            return false;
517	        }
518	        int at = email.lastIndexOf('@');
519	        if (at < 0 || at == email.length() - 1) {
520	            return false;
521	        }
522	        String domain = email.substring(at + 1).toLowerCase();
523	        return DISPOSABLE_EMAIL_DOMAINS.contains(domain);
524	    }
