526	    /**
527	     * Whether the owner's city is approaching the per-city capacity limit of 50 owners: true when the
528	     * city already holds between 40 and 49 owners (counted the same way as the hard-limit rule, over
529	     * all owners with a matching, normalized city), otherwise false.
530	     */
531	    private boolean capacityWarning(String city) {
532	        String cityKey = normaliseIdentity(city);
533	        long ownersInCity = this.clinicService.findAllOwners().stream()
534	            .filter(existing -> normaliseIdentity(existing.getCity()).equals(cityKey))
535	            .count();
536	        return ownersInCity >= 40 && ownersInCity <= 49;
537	    }
