585	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
586	    @Override
587	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
588	        String idempotencyKey = currentIdempotencyKey();
589	        if (idempotencyKey != null) {
590	            Integer existingId = this.idempotentCreations.get(idempotencyKey);
591	            if (existingId != null) {
592	                Owner existing = this.clinicService.findOwnerById(existingId);
593	                if (existing != null) {
594	                    existing.setHouseholdSize(householdSize(existing));
595	                    OwnerDto existingDto = ownerMapper.toOwnerDto(existing);
596	                    existingDto.setMembershipLevel(cappedMembershipLevel(existing));
597	                    existingDto.setBulkSignupWarning(existing.getRegistrationDate() != null
598	                        && ownersCreatedOn(existing.getRegistrationDate()) > 80);
599	                    existingDto.setCapacityWarning(capacityWarning(existing.getCity()));
600	                    return new ResponseEntity<>(existingDto, HttpStatus.OK);
601	                }
602	            }
603	        }
604	        String telephone = toE164(ownerFieldsDto.getTelephone());
605	        if (telephone == null) {
606	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
607	        }
608	        String email = ownerFieldsDto.getEmail();
609	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
610	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
611	        }
612	        if (isDisposableEmailDomain(email)) {
613	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
614	        }
615	        // Structured address is preferred when supplied (a non-blank 'addressLine1'); otherwise the
616	        // flat 'address' input is used for backward compatibility. Normalization applies to whichever
617	        // fields are supplied, and the composed 'address' is the normalized addressLine1 with the
618	        // normalized addressLine2 appended after a single space when present.
619	        String addressLine1 = normaliseAddress(ownerFieldsDto.getAddressLine1());
620	        String addressLine2 = normaliseAddress(ownerFieldsDto.getAddressLine2());
621	        boolean structuredAddress = !addressLine1.isEmpty();
622	        String address;
623	        if (structuredAddress) {
624	            address = addressLine2.isEmpty() ? addressLine1 : addressLine1 + " " + addressLine2;
625	        } else {
626	            address = normaliseAddress(ownerFieldsDto.getAddress());
627	        }
628	        if (address.isEmpty()) {
629	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
630	        }
631	        String postcode = ownerFieldsDto.getPostcode();
632	        if (postcode != null && !isPostcodeValid(postcode, ownerFieldsDto.getCity())) {
633	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
634	        }
635	        if (ownerFieldsDto.getRegistrationDate() != null
636	            && ownerFieldsDto.getRegistrationDate().isAfter(LocalDate.now())) {
637	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
638	        }
639	        LocalDate effectiveDate = ownerFieldsDto.getRegistrationDate() != null
640	            ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
641	        LocalDate registrationDate = toBusinessDay(effectiveDate);
642	        long ownersCreatedThatDay = this.clinicService.findAllOwners().stream()
643	            .map(Owner::getRegistrationDate)
644	            .filter(existing -> existing != null)
645	            .map(OwnerRestControllerV1::toBusinessDay)
646	            .filter(registrationDate::equals)
647	            .count();
648	        if (ownersCreatedThatDay >= 100) {
649	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
650	        }
651	        String cityKey = normaliseIdentity(ownerFieldsDto.getCity());
652	        long ownersInCity = this.clinicService.findAllOwners().stream()
653	            .filter(existing -> normaliseIdentity(existing.getCity()).equals(cityKey))
654	            .count();
655	        if (ownersInCity >= 50) {
656	            return new ResponseEntity<>(HttpStatus.CONFLICT);
657	        }
658	        String lastNameKey = normaliseIdentity(ownerFieldsDto.getLastName());
659	        // The household is deterministically keyed on (normalized last name, postcode): every owner
660	        // with a postcode belongs to the household identified by this computed id, and owners sharing
661	        // a last name and postcode share it automatically. A new owner may join an existing household;
662	        // the household ceiling below (rather than a hard rejection) governs its membership level.
663	        String householdId = (postcode == null) ? null : householdId(lastNameKey, postcode);
664	        // Duplicate detection is the single identity key (normalized telephone, lower-cased email and
665	        // Soundex of the last name). A candidate whose key collides with an existing, non-deleted
666	        // owner is a hard duplicate (409); the household id no longer participates in this decision.
667	        String identityKey = OwnerIdentity.identityKey(telephone, email, ownerFieldsDto.getLastName());
668	        boolean identityInUse = this.clinicService.findAllOwners().stream()
669	            .filter(existing -> !existing.isDeleted())
670	            .anyMatch(existing -> OwnerIdentity.identityKey(toE164(existing.getTelephone()),
671	                existing.getEmail(), existing.getLastName()).equals(identityKey));
672	        if (identityInUse) {
673	            return new ResponseEntity<>(HttpStatus.CONFLICT);
674	        }
675	        // Soft match: an existing, non-deleted owner sharing this owner's postcode and last-name
676	        // Soundex but with a different identity key (e.g. a different telephone) is not a hard
677	        // duplicate, but the new owner is flagged as a possible duplicate of it.
678	        String lastNameSoundex = OwnerIdentity.soundex(ownerFieldsDto.getLastName());
679	        Integer possibleDuplicateOf = (postcode == null) ? null
680	            : this.clinicService.findAllOwners().stream()
681	                .filter(existing -> !existing.isDeleted())
682	                .filter(existing -> postcode.equals(existing.getPostcode()))
683	                .filter(existing -> lastNameSoundex.equals(OwnerIdentity.soundex(existing.getLastName())))
684	                .filter(existing -> !OwnerIdentity.identityKey(toE164(existing.getTelephone()),
685	                    existing.getEmail(), existing.getLastName()).equals(identityKey))
686	                .map(Owner::getId)
687	                .findFirst()
688	                .orElse(null);
689	        String firstNameKey = normaliseIdentity(ownerFieldsDto.getFirstName());
690	        int namesakeCount = (int) this.clinicService.findAllOwners().stream()
691	            .filter(existing ->
692	                normaliseIdentity(existing.getFirstName()).equals(firstNameKey)
693	                    && normaliseIdentity(existing.getLastName()).equals(lastNameKey))
694	            .count();
695	        HttpHeaders headers = new HttpHeaders();
696	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
697	        owner.setNamesakeCount(namesakeCount);
698	        owner.setAddress(address);
699	        if (structuredAddress) {
700	            owner.setAddressLine1(addressLine1);
701	            owner.setAddressLine2(addressLine2.isEmpty() ? null : addressLine2);
702	        } else {
703	            owner.setAddressLine1(null);
704	            owner.setAddressLine2(null);
705	        }
706	        owner.setTelephone(telephone);
707	        owner.setEmail(email == null ? null : email.toLowerCase());
708	        owner.setRegistrationDate(registrationDate);
709	        owner.setMemberId(deduplicateMemberId(nextMemberId(
710	            region(postcode, owner.getCity()), registrationDate, telephone, owner.getLastName())));
711	        owner.setHouseholdId(householdId);
712	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
713	        this.clinicService.saveOwner(owner);
714	        if (idempotencyKey != null) {
715	            this.idempotentCreations.put(idempotencyKey, owner.getId());
716	        }
717	        owner.setHouseholdSize(householdSize(owner));
718	        Integer membershipLevel = cappedMembershipLevel(owner);
719	        AUDIT.info("owner created: id={} memberId={} registrationDate={} membershipLevel={}",
720	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), membershipLevel);
721	        // Immutable structured event carrying the owner's current primary identifier (the
722	        // unified memberId), with a monotonic sequence.
723	        AUDIT.info(new OwnerCreatedEvent(CREATE_SEQUENCE.incrementAndGet(), owner.getId(),
724	            owner.getMemberId(), membershipLevel).toJson());
725	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
726	        ownerDto.setMembershipLevel(membershipLevel);
727	        ownerDto.setBulkSignupWarning(ownersCreatedThatDay > 80);
728	        ownerDto.setCapacityWarning(capacityWarning(owner.getCity()));
729	        headers.setLocation(UriComponentsBuilder.newInstance()
730	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
731	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
732	    }
733	
734	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
735	    @Override
736	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
737	        String telephone = toE164(ownerFieldsDto.getTelephone());
738	        if (telephone == null) {
739	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
740	        }
741	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
742	        if (currentOwner == null) {
743	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
744	        }
745	        String email = ownerFieldsDto.getEmail();
746	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
747	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
748	        }
749	        String addressLine1 = normaliseAddress(ownerFieldsDto.getAddressLine1());
750	        String addressLine2 = normaliseAddress(ownerFieldsDto.getAddressLine2());
751	        if (!addressLine1.isEmpty()) {
752	            currentOwner.setAddressLine1(addressLine1);
753	            currentOwner.setAddressLine2(addressLine2.isEmpty() ? null : addressLine2);
754	            currentOwner.setAddress(addressLine2.isEmpty() ? addressLine1 : addressLine1 + " " + addressLine2);
755	        } else {
756	            currentOwner.setAddressLine1(null);
757	            currentOwner.setAddressLine2(null);
758	            currentOwner.setAddress(normaliseAddress(ownerFieldsDto.getAddress()));
759	        }
760	        currentOwner.setCity(ownerFieldsDto.getCity());
761	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
762	        currentOwner.setLastName(ownerFieldsDto.getLastName());
763	        currentOwner.setTelephone(telephone);
764	        currentOwner.setEmail(email == null ? null : email.toLowerCase());
765	        this.clinicService.saveOwner(currentOwner);
766	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
767	    }
768	
769	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
770	    @Transactional
771	    @Override
772	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
773	        Owner owner = this.clinicService.findOwnerById(ownerId);
774	        if (owner == null) {
775	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
776	        }
777	        // Soft delete: flag the owner deleted and retain the record so it can still be read back.
778	        owner.setDeleted(true);
779	        this.clinicService.saveOwner(owner);
780	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
781	    }
782	
783	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
784	    @Override
785	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
786	        Owner owner = this.clinicService.findOwnerById(ownerId);
787	        if (owner == null) {
788	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
789	        }
790	        HttpHeaders headers = new HttpHeaders();
791	        Pet pet = petMapper.toPet(petFieldsDto);
792	        owner.setId(ownerId);
793	        pet.setOwner(owner);
794	        pet.getType().setName(null);
795	        this.clinicService.savePet(pet);
796	        PetDto petDto = petMapper.toPetDto(pet);
797	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
798	            .buildAndExpand(pet.getId()).toUri());
799	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
800	    }
801	
802	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
803	    @Override
804	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
805	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
806	        if (currentOwner != null) {
807	            Pet currentPet = this.clinicService.findPetById(petId);
808	            if (currentPet != null) {
809	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
810	                currentPet.setName(petFieldsDto.getName());
811	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
812	                this.clinicService.savePet(currentPet);
813	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
814	            }
815	        }
816	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
817	    }
818	
819	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
820	    @Override
821	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
822	        HttpHeaders headers = new HttpHeaders();
823	        Visit visit = visitMapper.toVisit(visitFieldsDto);
824	        Pet pet = new Pet();
825	        pet.setId(petId);
826	        visit.setPet(pet);
827	        this.clinicService.saveVisit(visit);
828	        VisitDto visitDto = visitMapper.toVisitDto(visit);
829	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
830	            .buildAndExpand(visit.getId()).toUri());
831	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
832	    }
833	
834	
835	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
836	    @Override
